import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTheme } from '../contexts/ThemeContext';
import NotificacaoDropdown from './common/NotificacaoDropdown';

interface LayoutProps {
  children: React.ReactNode;
  title?: string;
}

const LayoutModern: React.FC<LayoutProps> = ({ children, title }) => {
  const { user, logout } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const navigate = useNavigate();
  const [sidebarOpen, setSidebarOpen] = useState(true);

  const isAdmin = user?.role === 'ADMIN';

  const adminMenuItems = [
    { id: 'dashboard', title: 'Dashboard', path: '/admin/dashboard', icon: '📊' },
    { id: 'clientes', title: 'Gestão de Clientes', path: '/admin/clientes', icon: '👥' },
    { id: 'quartos', title: 'Gestão de Quartos', path: '/admin/quartos', icon: '🏨' },
    { id: 'funcionarios', title: 'Gestão de Funcionários', path: '/admin/funcionarios', icon: '👔' },
    { id: 'alterar-status', title: 'Alterar Status Quarto', path: '/admin/alterar-status', icon: '🔧' },
    { id: 'relatorios', title: 'Relatórios', path: '/admin/relatorios', icon: '📈' },
  ];

  const userMenuItems = [
    { id: 'criar-reserva', title: 'Criar Reserva', path: '/user/criar-reserva', icon: '📝' },
    { id: 'consultar-reservas', title: 'Consultar Reservas', path: '/user/consultar-reservas', icon: '🔍' },
    { id: 'cancelar-reserva', title: 'Cancelar Reserva', path: '/user/cancelar-reserva', icon: '❌' },
    { id: 'checkin', title: 'Realizar Check-in', path: '/user/checkin', icon: '🏨' },
    { id: 'checkout', title: 'Realizar Check-out', path: '/user/checkout', icon: '🚪' },
    { id: 'status-quartos', title: 'Ver Status Quartos', path: '/user/status-quartos', icon: '📊' },
    { id: 'limpeza', title: 'Solicitar Limpeza', path: '/user/limpeza', icon: '🧹' },
    { id: 'manutencao', title: 'Solicitar Manutenção', path: '/user/manutencao', icon: '🔧' },
    { id: 'consultar-cliente', title: 'Consultar Cliente', path: '/user/consultar-cliente', icon: '👤' },
  ];

  const menuItems = isAdmin ? adminMenuItems : userMenuItems;

  const handleLogoClick = () => {
    navigate('/');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-900 dark:to-slate-800">
      <div className="flex h-screen overflow-hidden">
        {/* Sidebar */}
        <aside className={`${sidebarOpen ? 'w-64' : 'w-20'} bg-white dark:bg-slate-800 shadow-xl border-r border-slate-200 dark:border-slate-700 transition-all duration-300 ease-in-out flex flex-col`}>
          {/* Logo */}
          <div className="p-4 border-b border-slate-200 dark:border-slate-700">
            <button
              onClick={handleLogoClick}
              className="flex items-center space-x-3 w-full hover:bg-slate-50 dark:hover:bg-slate-700 rounded-lg p-3 transition-colors duration-200"
              title="Ir para o Dashboard"
            >
              <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-blue-600 rounded-xl flex items-center justify-center flex-shrink-0">
                <span className="text-white text-lg font-bold">H</span>
              </div>
              {sidebarOpen && (
                <div className="text-left">
                  <h2 className="text-lg font-bold text-slate-900 dark:text-white">Hotel Pro</h2>
                  {title && (
                    <p className="text-xs text-slate-500 dark:text-slate-400 mt-1 truncate">{title}</p>
                  )}
                </div>
              )}
            </button>
          </div>

          {/* Menu */}
          <nav className="flex-1 p-4 overflow-y-auto">
            <div className="space-y-2">
              {menuItems.map((item) => (
                <a
                  key={item.id}
                  href={item.path}
                  className={`flex items-center ${sidebarOpen ? 'space-x-3' : 'justify-center'} px-3 py-3 text-sm font-medium rounded-lg text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700 hover:text-slate-900 dark:hover:text-white transition-all duration-200 group`}
                >
                  <span className="text-xl flex-shrink-0">{item.icon}</span>
                  {sidebarOpen && (
                    <span className="truncate">{item.title}</span>
                  )}
                </a>
              ))}
            </div>
          </nav>

          {/* User Info */}
          <div className="p-4 border-t border-slate-200 dark:border-slate-700">
            <div className={`flex items-center ${sidebarOpen ? 'space-x-3' : 'justify-center'}`}>
              <div className="w-10 h-10 bg-gradient-to-br from-purple-500 to-purple-600 rounded-full flex items-center justify-center flex-shrink-0">
                <span className="text-white font-bold">
                  {user?.username?.charAt(0).toUpperCase()}
                </span>
              </div>
              {sidebarOpen && (
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-slate-900 dark:text-white truncate">
                    {user?.username}
                  </p>
                  <p className="text-xs text-slate-500 dark:text-slate-400">
                    {user?.role}
                  </p>
                </div>
              )}
            </div>
          </div>
        </aside>

        {/* Main Content */}
        <div className="flex-1 flex flex-col overflow-hidden">
          {/* Header */}
          <header className="bg-white dark:bg-slate-800 shadow-sm border-b border-slate-200 dark:border-slate-700">
            <div className="flex items-center justify-between px-6 py-4">
              <div className="flex items-center space-x-4">
                <button
                  onClick={() => setSidebarOpen(!sidebarOpen)}
                  className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors duration-200"
                  title="Toggle Sidebar"
                >
                  <svg className="w-5 h-5 text-slate-600 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                  </svg>
                </button>

                {title && (
                  <div>
                    <h1 className="text-xl font-semibold text-slate-900 dark:text-white">{title}</h1>
                  </div>
                )}
              </div>

              <div className="flex items-center space-x-4">
                {/* Notificações */}
                <NotificacaoDropdown />

                {/* Theme Toggle */}
                <button
                  onClick={toggleTheme}
                  className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors duration-200"
                  title="Alternar tema"
                >
                  {theme === 'light' ? (
                    <svg className="w-5 h-5 text-slate-600 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
                    </svg>
                  ) : (
                    <svg className="w-5 h-5 text-slate-600 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
                    </svg>
                  )}
                </button>

                {/* User Menu */}
                <div className="relative">
                  <button
                    onClick={logout}
                    className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 transition-colors duration-200"
                    title="Sair"
                  >
                    <svg className="w-5 h-5 text-slate-600 dark:text-slate-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                    </svg>
                  </button>
                </div>
              </div>
            </div>
          </header>

          {/* Content */}
          <main className="flex-1 overflow-y-auto">
            {children}
          </main>
        </div>
      </div>
    </div>
  );
};

export default LayoutModern;
